/*
 * @file QmlTypes.cpp
 * @brief Keeps the generated registration of the Telemetry.UX module linked.
 * @author Ruslan Kovtun (shpegun60)
 * SPDX-License-Identifier: MIT
 */
#include "QmlTypes.hpp"
#include <QtCore/QtGlobal>

// Generated by qt_add_qml_module for the module's QML_ELEMENT types.
void qml_register_types_Telemetry_UX();

namespace telemetry::ux {
void registerQmlTypes()
{
	// A reference the linker cannot drop: it keeps the registration object,
	// which registers the types itself. Calling it as well would register twice.
	volatile auto registration = &qml_register_types_Telemetry_UX;
	Q_UNUSED(registration);
}
} // namespace telemetry::ux
